#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, C;
    cin >> N >> K >> C;

    vector<long long> prefix(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        long long x;
        cin >> x;
        prefix[i] = prefix[i - 1] + x;
    }

    const long long INF = LLONG_MAX / 4;
    vector<long long> prev(N + 1, 0), cur(N + 1, INF);

    for (int j = 1; j <= K; ++j) {
        fill(cur.begin(), cur.end(), INF);

        for (int i = j * C; i <= N; ++i) {
            cur[i] = cur[i - 1];
            long long covered = prefix[i] - prefix[i - C];
            cur[i] = min(cur[i], prev[i - C] + covered);
        }

        prev.swap(cur);
    }

    cout << prefix[N] - prev[N] << '\n';
